const CLIENT_MODULES = ['ui-core.js', 'components.js', 'dashboard.js', 'chat.js', 'models.js', 'versions.js', 'server-config.js', 'logs.js', 'diagnostics.js']

function LazyLlamaApp(props) {
  const [loaded, setLoaded] = React.useState(false)
  const [error, setError] = React.useState(null)
  React.useEffect(function () {
    let alive = true
    const getCode = async function (name) {
      // Self-contained bundles inline the modules; the live dynamic mount
      // fetches them over the package RPC instead.
      if (typeof INLINED_CLIENT_MODULES !== 'undefined' && INLINED_CLIENT_MODULES[name]) {
        return { ok: true, code: INLINED_CLIENT_MODULES[name] }
      }
      try {
        const res = await props.host.call('llama.getClientModule', { name })
        if (!res || res.ok !== true) throw new Error('module ' + name + ': ' + ((res && res.message) || 'read failed'))
        return res
      } catch (e) {
        throw new Error('host call failed for ' + name + ': ' + String(e && e.message))
      }
    }
    const load = async function () {
      for (const name of CLIENT_MODULES) {
        const res = await getCode(name)
        const factory = eval('(' + res.code + ')')
        factory(React, props.LLAMA)
      }
      if (alive) setLoaded(true)
    }
    load().catch(function (e) {
      if (alive) setError(String(e && e.message ? e.message : e))
    })
    return function () { alive = false }
  }, [])
  if (error !== null) {
    return React.createElement('div', { className: 'llama-app' },
      React.createElement('div', { className: 'llama-notice', 'data-tone': 'err' },
        React.createElement('strong', null, 'llama.cpp UI failed to load'),
        React.createElement('pre', { className: 'llama-code', style: { marginTop: 8 } }, error)))
  }
  if (!loaded) {
    return React.createElement('div', { className: 'llama-app' },
      React.createElement('div', { className: 'llama-empty' },
        React.createElement('span', { className: 'llama-spin' }),
        React.createElement('span', null, 'Loading llama.cpp manager…')))
  }
  const App = props.LLAMA.Client.ui['ui-core'] && props.LLAMA.Client.ui['ui-core'].App
  if (!App) {
    return React.createElement('div', { className: 'llama-app' },
      React.createElement('div', { className: 'llama-notice', 'data-tone': 'err' }, 'ui-core module did not register an App'))
  }
  return React.createElement(App, props)
}

return {
  name: 'llama-cpp-manager-client',
  inject: ['slots', 'timer'],
  apply(ctx) {
    const rawTimer = ctx.timer
    styles.insert(BASE_CSS)

    const LLAMA = { Client: { ui: {}, styles } }
    LLAMA.Client.call = function (method, args) {
      return host.call('llama.call', { method, args: args === undefined ? {} : args })
    }
    LLAMA.Client.state = function () {
      return host.call('llama.state', {})
    }
    LLAMA.Client.timer = rawTimer
    LLAMA.Client.poll = function (fn, ms) {
      return rawTimer.interval(function () {
        try { fn() } catch (_e) { /* noop */ }
      }, ms)
    }

    ctx.slots.inject('settings.section', function () {
      return ctx.slots.register(
        { name: 'settings.section', id: 'llama-cpp', order: 25, label: function () { return 'llama.cpp' } },
        function (props) {
          return React.createElement(LazyLlamaApp, {
            close: props && props.close,
            host,
            LLAMA,
          })
        },
      )
    })
  },
}
